ids = [p["case_id"] for p in P]
assert len(P) == 20, len(P)
assert len(set(ids)) == 20
for p in P:
    path = os.path.join(OUT, p["case_id"] + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(p, f, ensure_ascii=False, indent=1)
    # self-verify
    with open(path, encoding="utf-8") as f:
        q = json.load(f)
    assert q["case_id"] == p["case_id"]
    for k in ("prediction_text", "basis", "confidence", "trigger"):
        assert k in q, (p["case_id"], k)
    for k in ("changed_main", "reserve_used", "disputed", "reason"):
        assert k in q["trigger"], (p["case_id"], k)
    assert 0.0 <= q["confidence"] <= 1.0

total = sum(os.path.getsize(os.path.join(OUT, i + ".json")) for i in ids)
cm = sum(1 for p in P if p["trigger"]["changed_main"])
ru = sum(1 for p in P if p["trigger"]["reserve_used"])
di = sum(1 for p in P if p["trigger"]["disputed"])
print("written:", len(P))
print("total_bytes:", total)
print("trigger counts changed_main/reserve_used/disputed:", cm, ru, di)
